def analyze_pattern(inputs, outputs):
    """Analyze input/output pairs to determine what replacements are needed."""
    replacements = {}

    for inp, outp in zip(inputs, outputs):
        print(f"Input: '{inp}' -> Output: '{outp}'")
        # For each position, compare characters
        min_len = min(len(inp), len(outp))

        # Check character by character
        for i in range(min_len):
            if i < len(inp) and i < len(outp) and inp[i] != outp[i]:
                print(f"  Position {i}: '{inp[i]}' -> '{outp[i]}'")
                if inp[i] not in replacements:
                    replacements[inp[i]] = outp[i]
                elif replacements[inp[i]] != outp[i]:
                    print(f"    Conflict: {inp[i]} maps to both {replacements[inp[i]]} and {outp[i]}")

        # Handle length differences
        if len(inp) > len(outp):
            print(f"  Length decreased from {len(inp)} to {len(outp)}")
        elif len(outp) > len(inp):
            print(f"  Length increased from {len(inp)} to {len(outp)}")

    return replacements

inputs = ['yzybai', 'cfxc', 'hgyiiv', 'afgxi', 'jvgae']
outputs = ['yxybai', 'cfxc', 'haayiiv', 'afaaxi', 'fgvaaahj']

replacements = analyze_pattern(inputs, outputs)
print("All identified replacements:", replacements)

